import{_ as p,a0 as r,w as o,s as d,I as a,x as n,a1 as t,A as i,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何使用 VTY Shell 配置路由器 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 VTY Shell 配置路由器 | LCTT (202005) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 VTY Shell 配置路由器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 VTY Shell 配置路由器 | LCTT (202005) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202005/20200520 How to configure your router using VTY shell","title":"如何使用 VTY Shell 配置路由器","tag":"202005","desc":""},"relativePath":"202005/20200520 How to configure your router using VTY shell.md","filePath":"[post].md"}'),u={name:"202005/20200520 How to configure your router using VTY shell.md"};function h(g,s,f,c,k,b){const e=r("Link");return o(),d("div",null,[s[33]||(s[33]=a("h1",{id:"如何使用-vty-shell-配置路由器",tabindex:"-1"},[n("如何使用 VTY Shell 配置路由器 "),a("a",{class:"header-anchor",href:"#如何使用-vty-shell-配置路由器","aria-label":"Permalink to “如何使用 VTY Shell 配置路由器”"},"​")],-1)),s[34]||(s[34]=a("blockquote",null,[a("p",null,"FRR（free range routing）給了你實現多種協議的選擇。本指南將幫助你入門。")],-1)),s[35]||(s[35]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202005/31/122310xi9aag5iqihqgcxl.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=n("最近，我寫了一篇文章，解釋瞭如何使用 ",-1)),t(e,{href:"https://linux.cn/article-12199-1.html"},{default:i(()=>[...s[0]||(s[0]=[n("Quagga",-1)])]),_:1}),s[2]||(s[2]=n(" 路由套件實現",-1)),s[3]||(s[3]=a("ruby",null,[n("開放式最短路徑優先"),a("rt",null,"Open Shortest Path First")],-1)),s[4]||(s[4]=n("（OSPF）。可以使用多個軟件套件代替 Quagga 來實現不同的路由協議。其中一種是 FRR（free range routing）。",-1))]),s[36]||(s[36]=a("h3",{id:"frr",tabindex:"-1"},[n("FRR "),a("a",{class:"header-anchor",href:"#frr","aria-label":"Permalink to “FRR”"},"​")],-1)),a("p",null,[t(e,{href:"https://en.wikipedia.org/wiki/FRRouting"},{default:i(()=>[...s[5]||(s[5]=[n("FRR",-1)])]),_:1}),s[6]||(s[6]=n(" 是一個路由軟件套件，它衍生自 Quagga，並在 GNU GPL2 許可下分發。與 Quagga 一樣，它為類 Unix 平台提供了所有主要路由協議的實現，例如 OSPF、",-1)),s[7]||(s[7]=a("ruby",null,[n("路由信息協議"),a("rt",null,"Routing Information Protocol")],-1)),s[8]||(s[8]=n("（RIP）、",-1)),s[9]||(s[9]=a("ruby",null,[n("邊界網關協議"),a("rt",null,"Border Gateway Protocol")],-1)),s[10]||(s[10]=n("（BGP） 和",-1)),s[11]||(s[11]=a("ruby",null,[n("中間系統到中間系統"),a("rt",null,"Intermediate system-to-intermediate system")],-1)),s[12]||(s[12]=n(" （IS-IS）。",-1))]),s[37]||(s[37]=l('<p>開發了 Quagga 的一些公司，例如 Big Switch Networks、Cumulus、Open Source Routing 和 6wind，創建了 FRR 以在 Quagga 的良好基礎上進行改善。</p><h4 id="體系結構" tabindex="-1">體系結構 <a class="header-anchor" href="#體系結構" aria-label="Permalink to “體系結構”">​</a></h4><p>FRR 是一組守護進程，它們可以共同構建路由表。每個主協議都在其自己的守護進程中實現，並且這些守護進程與獨立於協議的核心守護進程 Zebra 通信，後者提供內核路由表更新、接口查找以及不同路由協議之間路由的重新分配。每個特定協議的守護進程負責運行相關協議並根據交換的信息構建路由表。</p><p><img src="https://opensource.com/sites/default/files/uploads/frr_architecture.png" alt="FRR architecture" title="FRR architecture"></p><h3 id="vty-shell" tabindex="-1">VTY shell <a class="header-anchor" href="#vty-shell" aria-label="Permalink to “VTY shell”">​</a></h3>',5)),a("p",null,[t(e,{href:"http://docs.frrouting.org/projects/dev-guide/en/latest/vtysh.html"},{default:i(()=>[...s[13]||(s[13]=[n("VTYSH",-1)])]),_:1}),s[14]||(s[14]=n(" 是 FRR 路由引擎的集成 shell。它將每個守護進程中定義的所有 CLI 命令合併，並在單個 shell 中將它們呈現給用户。它提供了類似於 Cisco 的命令列模式，並且許多命令與 Cisco IOS 命令相似。CLI 有不同的模式，某些命令僅在特定模式下可用。",-1))]),s[38]||(s[38]=l('<h3 id="設置" tabindex="-1">設置 <a class="header-anchor" href="#設置" aria-label="Permalink to “設置”">​</a></h3><p>在本教程中，我們將使用 FRR 配置動態路由來實現路由信息協議（RIP）。我們可以通過兩種方式來做到這一點：在編輯器中編輯協議守護進程配置文件或使用 VTY Shell。在此例中，我們將使用 VTY shell。我們的設置包括兩個名為 Alpha 和 Beta 的 CentOS 7.7 主機。這兩台主機都有兩個網絡接口，並共享對 192.168.122.0/24 網絡的訪問。我們將廣播 10.12.11.0/24 和 10.10.10.0/24 網絡的路由。</p><p>對於主機 Alpha：</p><ul><li>eth0 IP：192.168.122.100/24</li><li>網關：192.168.122.1</li><li>eth1 IP：10.10.10.12/24</li></ul><p>對於主機 Beta：</p><ul><li>eth0 IP：192.168.122.50/24</li><li>網關：192.168.122.1</li><li>eth1 IP：10.12.11.12/24</li></ul><h4 id="安裝軟件包" tabindex="-1">安裝軟件包 <a class="header-anchor" href="#安裝軟件包" aria-label="Permalink to “安裝軟件包”">​</a></h4>',7)),a("p",null,[s[16]||(s[16]=n("首先，我們需要在兩台主機上都安裝 FRR 軟件包。可以按照",-1)),t(e,{href:"http://docs.frrouting.org/projects/dev-guide/en/latest/building-frr-for-centos7.html"},{default:i(()=>[...s[15]||(s[15]=[n("官方 FRR 文檔",-1)])]),_:1}),s[17]||(s[17]=n("中的説明進行操作。",-1))]),s[39]||(s[39]=l(`<h4 id="啓用-ip-轉發" tabindex="-1">啓用 IP 轉發 <a class="header-anchor" href="#啓用-ip-轉發" aria-label="Permalink to “啓用 IP 轉發”">​</a></h4><p>對於路由，我們需要在兩台主機上都啓用 IP 轉發，因為這將由 Linux 內核執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sysctl -w net.ipv4.conf.all.forwarding = 1</span></span>
<span class="line"><span>sysctl -w net.ipv6.conf.all.forwarding = 1</span></span>
<span class="line"><span>sysctl -p</span></span></code></pre></div><h4 id="啓用-ripd-守護進程" tabindex="-1">啓用 RIPD 守護進程 <a class="header-anchor" href="#啓用-ripd-守護進程" aria-label="Permalink to “啓用 RIPD 守護進程”">​</a></h4><p>安裝後，所有配置文件將保存在 <code>/etc/frr</code> 目錄中。 必須通過編輯 <code>/etc/frr/daemons</code> 文件顯式啓用守護進程。該文件確定啓動 FRR 服務時激活哪些守護進程。要啓用特定的守護進程，只需將相應的 <code>no</code> 改為 <code>yes</code>。之後的服務重啓將啓動守護進程。</p><p><img src="https://opensource.com/sites/default/files/uploads/frr_daemon_restart.png" alt="FRR daemon restart" title="FRR daemon restart"></p><h4 id="防火牆配置" tabindex="-1">防火牆配置 <a class="header-anchor" href="#防火牆配置" aria-label="Permalink to “防火牆配置”">​</a></h4><p>由於 RIP 協議使用 UDP 作為傳輸協議，並被分配了 520 端口，因此我們需要在 <code>firewalld</code> 配置中允許該端口。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --add-port=520/udp –permanent</span></span>
<span class="line"><span>firewalld-cmd -reload</span></span></code></pre></div><p>現在，我們可以使用以下命令啓動 FRR 服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl start frr</span></span></code></pre></div><h4 id="使用-vty-進行配置" tabindex="-1">使用 VTY 進行配置 <a class="header-anchor" href="#使用-vty-進行配置" aria-label="Permalink to “使用 VTY 進行配置”">​</a></h4><p>現在，我們需要使用 VTY Shell 配置 RIP。</p><p>在主機 Alpha 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@alpha ~]# vtysh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hello, this is FRRouting (version 7.2RPKI).</span></span>
<span class="line"><span>Copyright 1996-2005 Kunihiro Ishiguro, et al.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>alpha# configure terminal</span></span>
<span class="line"><span>alpha(config)# router rip</span></span>
<span class="line"><span>alpha(config-router)# network 192.168.122.0/24</span></span>
<span class="line"><span>alpha(config-router)# network 10.10.10.0/24</span></span>
<span class="line"><span>alpha(config-router)# route 10.10.10.5/24</span></span>
<span class="line"><span>alpha(config-router)# do write</span></span>
<span class="line"><span>Note: this version of vtysh never writes vtysh.conf</span></span>
<span class="line"><span>Building Configuration...</span></span>
<span class="line"><span>Configuration saved to /etc/frr/ripd.conf</span></span>
<span class="line"><span>Configuration saved to /etc/frr/staticd.conf</span></span>
<span class="line"><span>alpha(config-router)# do write memory</span></span>
<span class="line"><span>Note: this version of vtysh never writes vtysh.conf</span></span>
<span class="line"><span>Building Configuration...</span></span>
<span class="line"><span>Configuration saved to /etc/frr/ripd.conf</span></span>
<span class="line"><span>Configuration saved to /etc/frr/staticd.conf</span></span>
<span class="line"><span>alpha(config-router)# exit</span></span></code></pre></div><p>類似地，在主機 Beta 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@beta ~]# vtysh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hello, this is FRRouting (version 7.2RPKI).</span></span>
<span class="line"><span>Copyright 1996-2005 Kunihiro Ishiguro, et al.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>beta# configure terminal</span></span>
<span class="line"><span>beta(config)# router rip</span></span>
<span class="line"><span>beta(config-router)# network 192.168.122.0/24</span></span>
<span class="line"><span>beta(config-router)# network 10.12.11.0/24</span></span>
<span class="line"><span>beta(config-router)# do write</span></span>
<span class="line"><span>Note: this version of vtysh never writes vtysh.conf</span></span>
<span class="line"><span>Building Configuration...</span></span>
<span class="line"><span>Configuration saved to /etc/frr/zebra.conf</span></span>
<span class="line"><span>Configuration saved to /etc/frr/ripd.conf</span></span>
<span class="line"><span>Configuration saved to /etc/frr/staticd.conf</span></span>
<span class="line"><span>beta(config-router)# do write memory</span></span>
<span class="line"><span>Note: this version of vtysh never writes vtysh.conf</span></span>
<span class="line"><span>Building Configuration...</span></span>
<span class="line"><span>Configuration saved to /etc/frr/zebra.conf</span></span>
<span class="line"><span>Configuration saved to /etc/frr/ripd.conf</span></span>
<span class="line"><span>Configuration saved to /etc/frr/staticd.conf</span></span>
<span class="line"><span>beta(config-router)# exit</span></span></code></pre></div><p>完成後，像下面這樣檢查兩台主機路由：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@alpha ~]# ip route show</span></span>
<span class="line"><span>default via 192.168.122.1 dev eth0 proto static metric 100</span></span>
<span class="line"><span>10.10.10.0/24 dev eth1 proto kernel scope link src 10.10.10.12 metric 101</span></span>
<span class="line"><span>10.12.11.0/24 via 192.168.122.50 dev eth0 proto 189 metric 20</span></span>
<span class="line"><span>192.168.122.0/24 dev eth0 proto kernel scope link src 192.168.122.100 metric 100</span></span></code></pre></div><p>我們可以看到 Alpha 上的路由表通過 <code>192.168.122.50</code> 包含了 <code>10.12.11.0/24</code> 的條目，它是通過 RIP 提供的。</p><p>類似地，在 Beta 上，該表通過 <code>192.168.122.100</code> 包含了 <code>10.10.10.0/24</code> 的條目。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@beta ~]# ip route show</span></span>
<span class="line"><span>default via 192.168.122.1 dev eth0 proto static metric 100</span></span>
<span class="line"><span>10.10.10.0/24 via 192.168.122.100 dev eth0 proto 189 metric 20</span></span>
<span class="line"><span>10.12.11.0/24 dev eth1 proto kernel scope link src 10.12.11.12 metric 101</span></span>
<span class="line"><span>192.168.122.0/24 dev eth0 proto kernel scope link src 192.168.122.50 metric 100</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>如你所見，設置和配置相對簡單。要增加複雜性，我們可以向路由器添加更多的網絡接口，以為更多的網絡提供路由。可以在編輯器中編輯配置文件來進行配置，但是使用 VTY Shell 在單個組合會話中為我們提供了所有 FRR 守護進程的前端。</p><hr>`,25)),a("p",null,[s[19]||(s[19]=n("via: ",-1)),t(e,{href:"https://opensource.com/article/20/5/vty-shell"},{default:i(()=>[...s[18]||(s[18]=[n("https://opensource.com/article/20/5/vty-shell",-1)])]),_:1})]),a("p",null,[s[24]||(s[24]=n("作者：",-1)),t(e,{href:"https://opensource.com/users/noisybotnet"},{default:i(()=>[...s[20]||(s[20]=[n("M Umer",-1)])]),_:1}),s[25]||(s[25]=n(" 選題：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[21]||(s[21]=[n("lujun9972",-1)])]),_:1}),s[26]||(s[26]=n(" 譯者：",-1)),t(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[22]||(s[22]=[n("geekpi",-1)])]),_:1}),s[27]||(s[27]=n(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[23]||(s[23]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[30]||(s[30]=n("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[28]||(s[28]=[n("LCTT",-1)])]),_:1}),s[31]||(s[31]=n(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:i(()=>[...s[29]||(s[29]=[n("Linux中國",-1)])]),_:1}),s[32]||(s[32]=n(" 榮譽推出",-1))])])}const C=p(u,[["render",h]]);export{y as __pageData,C as default};
